WITH flattened AS (SELECT id, plan, val FROM price_tiers LATERAL VIEW OUTER EXPLODE(tier_prices) x AS val) SELECT *, SUM(val) OVER w_ordered AS plan_sum_val, MAX(val) OVER w_ordered AS plan_max_val, RANK() OVER w_recent AS val_rank, DENSE_RANK() OVER (ORDER BY val DESC NULLS LAST) AS val_dense_rank FROM flattened WINDOW w_ordered AS (PARTITION BY plan), w_recent AS (ORDER BY val DESC NULLS FIRST)
